import { test, expect } from '@playwright/test';

test.beforeEach(async ({ request }) => {
  await request.post('http://localhost:3180/api/_reset');
});

test('Ada submits Intro to Testing and Alan submits Flaky Tests; teacher filters by Flaky Tests', async ({ page }) => {
  // --- Ada submits "Intro to Testing" (a1) ---
  await page.goto('http://localhost:5180/#/student/s1');
  await expect(page.getByTestId('open-assignment-a1')).toBeVisible();
  await page.getByTestId('open-assignment-a1').click();

  await expect(page.getByTestId('quiz-title')).toBeVisible();
  await page.getByTestId('answer-q1-1').click();
  await page.getByTestId('answer-q2-1').click();
  await page.getByTestId('answer-q3-1').click();

  await expect(page.getByTestId('submit-quiz')).toBeEnabled();
  await page.getByTestId('submit-quiz').click();

  await expect(page.getByTestId('quiz-result')).toBeVisible();

  // --- Alan submits "Flaky Tests" (a3) ---
  await page.goto('http://localhost:5180/#/student/s2');
  await expect(page.getByTestId('open-assignment-a3')).toBeVisible();
  await page.getByTestId('open-assignment-a3').click();

  await expect(page.getByTestId('quiz-title')).toBeVisible();
  await page.getByTestId('answer-q1-0').click();
  await page.getByTestId('answer-q2-0').click();
  await page.getByTestId('answer-q3-0').click();

  await expect(page.getByTestId('submit-quiz')).toBeEnabled();
  await page.getByTestId('submit-quiz').click();

  await expect(page.getByTestId('quiz-result')).toBeVisible();

  // --- Teacher tab: verify both submissions are listed ---
  await page.goto('http://localhost:5180/#/teacher');
  await expect(page.getByTestId('submissions-table')).toBeVisible();

  const adaRow = page.getByTestId('submission-row-sub-1');
  const alanRow = page.getByTestId('submission-row-sub-2');

  await expect(adaRow).toBeVisible();
  await expect(alanRow).toBeVisible();

  // --- Filter by "Flaky Tests" ---
  await page.getByTestId('filter-assignment').selectOption('a3');

  // Alan's row (Flaky Tests) remains visible
  await expect(alanRow).toBeVisible();

  // Ada's row (Intro to Testing) is no longer visible
  await expect(adaRow).not.toBeVisible();

  // Confirm assignment list reflects the filter
  await expect(page.getByTestId('assignment-list')).not.toContainText('Intro to Testing');
  await expect(page.getByTestId('assignment-list')).toContainText('Flaky Tests');
});
